import sys

DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base(n, base):
    out = ""
    while n > 0:
        out = DIGITS[n % base] + out
        n //= base
    return out


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            print("ERROR")
            continue
        number, src, dst = parts
        src, dst = int(src), int(dst)
        if not (2 <= src <= 36 and 2 <= dst <= 36):
            print("ERROR")
            continue
        try:
            value = int(number, src)
        except ValueError:
            print("ERROR")
            continue
        if value == 0:
            print("0")
        elif value < 0:
            print("-" + to_base(-value, dst))
        else:
            print(to_base(value, dst))


if __name__ == "__main__":
    main()
